(7089683, 1079908, 104289, '<td valign="top">For me, if you had combined 2 images for depth of field to get the log in focus then this would be a winner</td>', 'For me, if you had combined 2 images for depth of field to get the log in focus then this would be a winner', '2013-08-19 14:56:50.000000', NULL, 1),
(7089694, 1079792, 114225, '<td valign="top">Looks like you missed the "portrait orientation" part of the challenge title. Too bad, it''s a nice landscape.</td>', 'Looks like you missed the "portrait orientation" part of the challenge title. Too bad, it''s a nice landscape.', '2013-08-19 15:29:44.000000', NULL, 1),
(7089695, 1079190, 114225, '<td valign="top">Looks like you missed the "portrait orientation" part of the challenge title.<br/>Also, watch out for blown sky highlights in this type of photo.</td>', 'Looks like you missed the "portrait orientation" part of the challenge title.Also, watch out for blown sky highlights in this type of photo.', '2013-08-19 15:30:26.000000', NULL, 1),
