(7089715, 1080004, 27421, '<td valign="top">I would have liked more of the falls.</td>', 'I would have liked more of the falls.', '2013-08-19 17:00:04.000000', NULL, 1),
(7089730, 1079926, 167390, '<td valign="top"><strike></strike></td>', '', '2013-08-19 17:48:26.000000', NULL, 1),
(7089744, 1079979, 152252, '<td valign="top">Definitely! When I look at it I think ''desolation in a big city''. Usually I see pictures of it with colorful night lights, and inviting night life. When I look at your picture I feel like it''s more real. A depiction of city that somewhere there is full of people who feel alone in a crowd. Maybe that''s not what you wanted to accomplish with the picture, nevertheless I love it.</td>', 'Definitely! When I look at it I think ''desolation in a big city''. Usually I see pictures of it with colorful night lights, and inviting night life. When I look at your picture I feel like it''s more real. A depiction of city that somewhere there is full of people who feel alone in a crowd. Maybe that''s not what you wanted to accomplish with the picture, nevertheless I love it.', '2013-08-19 18:44:30.000000', NULL, 1),
(7089815, 1080006, 10785, '<td valign="top">This would be much better in landscape orientation as the broad dark tree and empty sky makes this feel bottom heavy.</td>', 'This would be much better in landscape orientation as the broad dark tree and empty sky makes this feel bottom heavy.', '2013-08-19 21:33:39.000000', NULL, 1),
(7089816, 1079850, 10785, '<td valign="top">Having stood and overlooked this wonder, I know the majesty of those piercing mountains! I think this needs a little more sharpening to bring out some of the detail. I love the cloud on top and the light.</td>', 'Having stood and overlooked this wonder, I know the majesty of those piercing mountains! I think this needs a little more sharpening to bring out some of the detail. I love the cloud on top and the light.', '2013-08-19 21:37:24.000000', NULL, 1),
(7089817, 1079936, 10785, '<td valign="top">I like the layers and the use of tilted angle. Wish there was something in the scene to offset the sea of green color.</td>', 'I like the layers and the use of tilted angle. Wish there was something in the scene to offset the sea of green color.', '2013-08-19 21:39:16.000000', NULL, 1),
(7089843, 1079677, 133845, '<td valign="top">I think it''s a bit too much water.</td>', 'I think it''s a bit too much water.', '2013-08-19 22:28:17.000000', NULL, 1),
(7089989, 1079269, 114285, '<td valign="top">great scene, just wished you''d cropped off the water as it''s blown out and not very attractive to look at, neither does it do anything for the composition. Love the sky but once again with a bit of PP enhancing could of popped.</td>', 'great scene, just wished you''d cropped off the water as it''s blown out and not very attractive to look at, neither does it do anything for the composition. Love the sky but once again with a bit of PP enhancing could of popped.', '2013-08-20 06:27:10.000000', NULL, 1),
(7089990, 1079777, 114285, '<td valign="top">ok, I love glow but this is just a bit too much, nice scene though.</td>', 'ok, I love glow but this is just a bit too much, nice scene though.', '2013-08-20 06:27:45.000000', NULL, 1),
(7089991, 1079656, 114285, '<td valign="top">always wanted to see this, awesome POV, and love the clouds settling on the mountain.</td>', 'always wanted to see this, awesome POV, and love the clouds settling on the mountain.', '2013-08-20 06:30:45.000000', NULL, 1),
(7089993, 1079792, 114285, '<td valign="top">doh!!!</td>', 'doh!!!', '2013-08-20 06:31:13.000000', NULL, 1),
