(7090982, 1079955, 30712, '<td valign="top">Can I see reflections in a window?  Whatever it is that sweeps across the image it does detract from my enjoyment of your picture.</td>', 'Can I see reflections in a window?  Whatever it is that sweeps across the image it does detract from my enjoyment of your picture.', '2013-08-21 16:20:34.000000', NULL, 1),
(7090983, 1080006, 30712, '<td valign="top">This lonely tree lacks a little in character.  Maybe the image is a little flat and could benefit from more contrast.</td>', 'This lonely tree lacks a little in character.  Maybe the image is a little flat and could benefit from more contrast.', '2013-08-21 16:21:49.000000', NULL, 1),
(7090985, 1079283, 30712, '<td valign="top">Mysterious lighting can bring a sense of magic to an image but here it leaves a sense of gloom.  This may have been intended.  The result allows my focus on the picture to drift away to other things.</td>', 'Mysterious lighting can bring a sense of magic to an image but here it leaves a sense of gloom.  This may have been intended.  The result allows my focus on the picture to drift away to other things.', '2013-08-21 16:25:17.000000', NULL, 1),
